@startuml

class Traveller {
  + name : string
  + companyName : string
  + address : string
  + reliabilityRating : float
}

class TravelPreference {
  + description : string
}

class SearchCriteria {
  + city : string
  + arrivalDate : date
  + departureDate : date
  + numberOfRooms : int
  + roomType : string
  + minimumRating : int
  + maxCostPerNight : double
}

class Booking {
  + bookingIdentifier : string
  + price : double
  + cityArea : string
  + hotelRating : int
  + cancellationDeadline : datetime
  + isConfirmed : boolean
  + isCancelled : boolean
}

class PreliminaryBooking {
  + bookingIdentifier : string
  + price : double
  + cityArea : string
  + hotelRating : int
}

class SpecialOffer {
  + price : double
}

class CreditCardInfo {
  + cardNumber : string
  + expiryDate : date
}

class Hotel {
  + name : string
  + address : string
  + rating : int
}

class HotelChain {
  + name : string
}

class RoomType {
  + type : string
}

class Availability {
  + isFullyBooked : boolean
}

Traveller "1" -- "*" TravelPreference
Traveller "1" -- "*" Booking
Traveller "1" -- "0..1" CreditCardInfo
Traveller "1" -- "*" PreliminaryBooking
Traveller "1" -- "*" SpecialOffer

Booking "1" -- "1" Hotel
Booking "1" -- "1" CreditCardInfo
Booking "1" -- "1" RoomType

PreliminaryBooking "1" -- "0..*" SpecialOffer
PreliminaryBooking "1" -- "1" Traveller

Hotel "0..1" -- "0..*" HotelChain : run by
Hotel "1" -- "*" RoomType
Hotel "1" -- "*" Availability
RoomType "1" -- "0..*" Availability

@enduml

